contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test that a single donate call cannot increase c's balance by more than the supplied amount.
    // Parameters:
    //  - whaleAddr: arbitrary address (unused here except to satisfy signature diversity)
    //  - amt: the Ether amount we will send with donate
    function run(address whaleAddr, uint256 amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        // must have funds to send
        require(address(this).balance >= amt);

        // As deployer of c, this contract is owner; open to public so donate() can be called
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        uint256 balBefore = address(c).balance;

        bool reverted;
        c.donate{value: amt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = address(c).balance;

        // General rule: if the call reverted then balance unchanged; otherwise balance increased by at most amt
        assert((reverted && balAfter == balBefore) || (!reverted && balAfter >= balBefore && balAfter - balBefore <= amt));
    }

    // allow receiving Ether so require(address(this).balance >= amt) can be satisfied
    receive() external payable {}
}

