// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(address whaleAddr, uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amt);
        try c.OpenToThePublic() {} catch { return; }
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.donate{value: amt}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter = address(c).balance;
        assertTrue((reverted && balAfter == balBefore) || (!reverted && balAfter >= balBefore && balAfter - balBefore <= amt));
    }

    function testFuzz_run(address whaleAddr, uint256 amt) public {
        vm.assume(whaleAddr.code.length == 0 && uint160(whaleAddr) > 0xffff && whaleAddr != address(this) && whaleAddr != address(c) && whaleAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && whaleAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && whaleAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && whaleAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(whaleAddr, amt);
    }

    receive() external payable {}
}
